import { randomUUID } from 'node:crypto';

export class TodoError extends Error {
  constructor(message, status) {
    super(message);
    this.status = status;
  }
}

const MAX_TITLE = 200;

function normalizeTitle(title) {
  if (typeof title !== 'string') throw new TodoError('title must be a string', 400);
  const trimmed = title.trim();
  if (!trimmed) throw new TodoError('title is required', 400);
  if (trimmed.length > MAX_TITLE) throw new TodoError(`title must be at most ${MAX_TITLE} characters`, 400);
  return trimmed;
}

/** In-memory todo store. Returns copies so callers cannot mutate internal state. */
export function createTodoStore() {
  const todos = new Map();

  const find = (id) => {
    const todo = todos.get(id);
    if (!todo) throw new TodoError(`todo ${id} not found`, 404);
    return todo;
  };

  return {
    list() {
      return [...todos.values()].map((t) => ({ ...t }));
    },
    create(title) {
      const todo = { id: randomUUID(), title: normalizeTitle(title), done: false, createdAt: new Date().toISOString() };
      todos.set(todo.id, todo);
      return { ...todo };
    },
    update(id, patch) {
      const current = find(id);
      const next = { ...current };
      if (patch.title !== undefined) next.title = normalizeTitle(patch.title);
      if (patch.done !== undefined) {
        if (typeof patch.done !== 'boolean') throw new TodoError('done must be a boolean', 400);
        next.done = patch.done;
      }
      todos.set(id, next);
      return { ...next };
    },
    remove(id) {
      find(id);
      todos.delete(id);
    },
  };
}

const list = document.querySelector('#list');
const form = document.querySelector('#add-form');
const input = document.querySelector('#title');
const errorBox = document.querySelector('#error');

async function api(path, options = {}) {
  const response = await fetch(path, { headers: { 'Content-Type': 'application/json' }, ...options });
  if (!response.ok) throw new Error((await response.json().catch(() => ({}))).error ?? response.statusText);
  return response.status === 204 ? null : response.json();
}

function render(todos) {
  list.replaceChildren(...todos.map((todo) => {
    const item = document.createElement('li');
    item.className = todo.done ? 'done' : '';
    const checkbox = Object.assign(document.createElement('input'), { type: 'checkbox', checked: todo.done });
    checkbox.addEventListener('change', () => run(() => api(`/api/todos/${todo.id}`, { method: 'PATCH', body: JSON.stringify({ done: checkbox.checked }) })));
    const title = document.createElement('span');
    title.textContent = todo.title; // textContent escapes user input
    const remove = Object.assign(document.createElement('button'), { className: 'delete', textContent: 'Delete' });
    remove.addEventListener('click', () => run(() => api(`/api/todos/${todo.id}`, { method: 'DELETE' })));
    item.append(checkbox, title, remove);
    return item;
  }));
}

async function run(action) {
  try {
    errorBox.textContent = '';
    await action();
    render(await api('/api/todos'));
  } catch (error) {
    errorBox.textContent = error.message;
  }
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  const title = input.value;
  input.value = '';
  run(() => api('/api/todos', { method: 'POST', body: JSON.stringify({ title }) }));
});

run(async () => {});

import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { extname, join, normalize } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createTodoStore, TodoError } from './todoStore.js';

const PUBLIC_DIR = fileURLToPath(new URL('../public/', import.meta.url));
const MAX_BODY = 64 * 1024;
const TYPES = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8' };

function send(res, status, body) {
  if (body === undefined) {
    res.writeHead(status).end();
    return;
  }
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' }).end(JSON.stringify(body));
}

async function readJson(req) {
  let size = 0;
  const chunks = [];
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY) throw new TodoError('request body too large', 413);
    chunks.push(chunk);
  }
  try {
    return chunks.length ? JSON.parse(Buffer.concat(chunks).toString('utf8')) : {};
  } catch {
    throw new TodoError('invalid JSON body', 400);
  }
}

async function serveStatic(res, pathname) {
  const relative = normalize(pathname === '/' ? 'index.html' : pathname.slice(1));
  if (relative.startsWith('..')) return send(res, 404, { error: 'not found' });
  try {
    const content = await readFile(join(PUBLIC_DIR, relative));
    res.writeHead(200, { 'Content-Type': TYPES[extname(relative)] ?? 'application/octet-stream' }).end(content);
  } catch {
    send(res, 404, { error: 'not found' });
  }
}

export function createApp(store = createTodoStore()) {
  return createServer(async (req, res) => {
    const { pathname } = new URL(req.url, 'http://localhost');
    try {
      if (pathname === '/api/todos' && req.method === 'GET') return send(res, 200, store.list());
      if (pathname === '/api/todos' && req.method === 'POST') return send(res, 201, store.create((await readJson(req)).title));
      const match = /^\/api\/todos\/([\w-]+)$/.exec(pathname);
      if (match && req.method === 'PATCH') return send(res, 200, store.update(match[1], await readJson(req)));
      if (match && req.method === 'DELETE') {
        store.remove(match[1]);
        return send(res, 204);
      }
      if (pathname.startsWith('/api/')) return send(res, 404, { error: 'not found' });
      if (req.method === 'GET') return serveStatic(res, pathname);
      return send(res, 405, { error: 'method not allowed' });
    } catch (error) {
      if (error instanceof TodoError) return send(res, error.status, { error: error.message });
      return send(res, 500, { error: 'internal error' });
    }
  });
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const port = Number(process.env.PORT ?? 3000);
  createApp().listen(port, '127.0.0.1', () => console.log(`todo-service on http://127.0.0.1:${port}`));
}

import { test, describe, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { createTodoStore } from '../src/todoStore.js';
import { createApp } from '../src/server.js';

describe('todo store', () => {
  test('creates, updates and removes todos', () => {
    const store = createTodoStore();
    const todo = store.create('  write tests  ');
    assert.equal(todo.title, 'write tests');
    assert.equal(todo.done, false);
    assert.equal(store.update(todo.id, { done: true }).done, true);
    store.remove(todo.id);
    assert.deepEqual(store.list(), []);
  });

  test('rejects invalid titles', () => {
    const store = createTodoStore();
    assert.throws(() => store.create('   '), /title is required/);
    assert.throws(() => store.create('x'.repeat(201)), /at most 200/);
  });

  test('reports unknown ids as not found', () => {
    assert.throws(() => createTodoStore().remove('missing'), (error) => error.status === 404);
  });
});

describe('HTTP API', () => {
  let server;
  let base;

  before(async () => {
    server = createApp();
    await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
    base = `http://127.0.0.1:${server.address().port}`;
  });

  after(() => new Promise((resolve) => server.close(resolve)));

  test('full todo lifecycle', async () => {
    const created = await fetch(`${base}/api/todos`, { method: 'POST', body: JSON.stringify({ title: 'ship it' }) });
    assert.equal(created.status, 201);
    const todo = await created.json();

    const patched = await fetch(`${base}/api/todos/${todo.id}`, { method: 'PATCH', body: JSON.stringify({ done: true }) });
    assert.equal((await patched.json()).done, true);

    const list = await (await fetch(`${base}/api/todos`)).json();
    assert.equal(list.length, 1);

    assert.equal((await fetch(`${base}/api/todos/${todo.id}`, { method: 'DELETE' })).status, 204);
    assert.equal((await fetch(`${base}/api/todos/${todo.id}`, { method: 'DELETE' })).status, 404);
  });

  test('validates input', async () => {
    const response = await fetch(`${base}/api/todos`, { method: 'POST', body: JSON.stringify({ title: '' }) });
    assert.equal(response.status, 400);
    const bad = await fetch(`${base}/api/todos`, { method: 'POST', body: '{not json' });
    assert.equal(bad.status, 400);
  });

  test('serves the web UI', async () => {
    const response = await fetch(`${base}/`);
    assert.equal(response.status, 200);
    assert.match(await response.text(), /<h1>Todos<\/h1>/);
  });
});
